// Capturas de la app real del sandbox (antes del #54): inicio, una respuesta con comandos y la
// consola de admin, en tema claro y oscuro. Uso: node capturar-app.mjs <carpeta> <prefijo>
import { chromium } from 'file:///./base-conocimiento/eval-100-preguntas/node_modules/playwright/index.mjs';

const [SALIDA, PREFIJO = 'antes'] = process.argv.slice(2);
const PREGUNTA = process.env.PREGUNTA ||
  'Dame los comandos exactos para desplegar el servicio, en un bloque de código bash.';
const navegador = await chromium.launch();
const errores = [];

for (const tema of ['light', 'dark']) {
  const pagina = await navegador.newPage({ viewport: { width: 1280, height: 860 }, colorScheme: tema });
  pagina.on('pageerror', (e) => errores.push(`${tema}: ${e.message}`));
  await pagina.goto('http://localhost:8080/');
  await pagina.waitForSelector('#pregunta');
  await pagina.screenshot({ path: `${SALIDA}/${PREFIJO}-inicio-${tema}.png` });
  if (tema === 'light' || process.env.PREGUNTAR_EN_OSCURO) {
    await pagina.fill('#pregunta', PREGUNTA);
    await pagina.click('#boton-preguntar');
    const inicio = Date.now();
    // En CPU una consulta tarda minutos: espera a que el turno diga "Respondido en" o "Listo en".
    await pagina.waitForFunction(() => /Respondido en|Listo en/.test(document.body.innerText),
      null, { timeout: 900_000, polling: 2000 });
    console.log(tema, 'respuesta en', Math.round((Date.now() - inicio) / 1000), 's');
    await pagina.waitForTimeout(1500);
    await pagina.screenshot({ path: `${SALIDA}/${PREFIJO}-respuesta-${tema}.png` });
    const texto = await pagina.evaluate(() => {
      const r = [...document.querySelectorAll('.turno-respuesta')].pop();
      return r ? r.textContent : '';
    });
    console.log('--- respuesta ---\n' + texto.slice(0, 1200));
  }
  await pagina.goto('http://localhost:8080/admin.html');
  await pagina.waitForTimeout(1500);
  await pagina.screenshot({ path: `${SALIDA}/${PREFIJO}-admin-${tema}.png` });
  await pagina.close();
}
console.log('errores', errores.length ? errores : 'ninguno');
await navegador.close();

