import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { chromium } from 'file:///./base-conocimiento/eval-100-preguntas/node_modules/playwright/index.mjs';

const RAIZ = '.';
const SALIDA = process.argv[2];
const TIPOS = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.json': 'application/json',
  '.bpmn': 'application/xml', '.svg': 'image/svg+xml', '.png': 'image/png', '.mjs': 'text/javascript' };
const servidor = http.createServer((req, res) => {
  const ruta = path.join(RAIZ, decodeURIComponent(req.url.split('?')[0]));
  fs.readFile(ruta, (e, d) => {
    if (e) { res.writeHead(404); res.end(); return; }
    res.writeHead(200, { 'Content-Type': (TIPOS[path.extname(ruta)] || 'application/octet-stream') + '; charset=utf-8' });
    res.end(d);
  });
}).listen(8125);

const navegador = await chromium.launch();
const errores = [];
const pagina = await navegador.newPage({ viewport: { width: 1600, height: 900 } });
pagina.on('pageerror', (e) => errores.push(e.message));

await pagina.goto('http://localhost:8125/proceso-operacional-con-ia/proceso-operacional-con-ia.html');
await pagina.waitForSelector('[data-element-id="c1"]', { timeout: 30000 });
await pagina.waitForTimeout(1500);
await pagina.screenshot({ path: `${SALIDA}/visor-general.png` });
for (const nodo of ['bo1', 'c1', 'c4a', 'c2', 'vw', 'c3', 'p1', 'cr', 'mg', 'c5']) {
  await pagina.click(`[data-element-id="${nodo}"]`);
  await pagina.waitForTimeout(700);
  await pagina.screenshot({ path: `${SALIDA}/visor-${nodo}.png` });
}

await pagina.goto('http://localhost:8125/playbook-sdlc-ia/Playbook-Fases/index.html');
await pagina.waitForTimeout(1500);
await pagina.screenshot({ path: `${SALIDA}/playbook-indice.png` });
await pagina.goto('http://localhost:8125/playbook-sdlc-ia/Playbook-Fases/04-ciclo-por-feature.html');
await pagina.waitForTimeout(1500);
await pagina.screenshot({ path: `${SALIDA}/playbook-f3.png` });

console.log('errores', errores.length ? errores : 'ninguno');
await navegador.close();
servidor.close();

