// En CPU una consulta tarda minutos. Si la busqueda literal no convence, el chat pide elegir
// una reformulacion (.turno-eleccion): se captura y se envia la primera opcion.
const fin = () => /Respondido en|Listo en/.test(document.body.innerText);
const eleccion = () => !!document.querySelector('.turno-eleccion:not(.oculto) .boton-eleccion');
await pagina.waitForFunction(`(${fin})() || (${eleccion})()`, null, { timeout: 900_000, polling: 2000 });
if (await pagina.evaluate(eleccion)) {
  await pagina.screenshot({ path: `${SALIDA}/${PREFIJO}-eleccion-${tema}.png` });
  await pagina.click('.turno-eleccion:not(.oculto) .boton-eleccion');
  await pagina.waitForFunction(fin, null, { timeout: 900_000, polling: 2000 });
}

