import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { chromium } from 'file:///./base-conocimiento/eval-100-preguntas/node_modules/playwright/index.mjs';

const RAIZ = '.';
const TIPOS = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.json': 'application/json',
  '.bpmn': 'application/xml', '.svg': 'image/svg+xml' };
const servidor = http.createServer((req, res) => {
  const ruta = path.join(RAIZ, decodeURIComponent(req.url.split('?')[0]));
  fs.readFile(ruta, (e, d) => {
    if (e) { res.writeHead(404); res.end(); return; }
    res.writeHead(200, { 'Content-Type': (TIPOS[path.extname(ruta)] || 'application/octet-stream') + '; charset=utf-8' });
    res.end(d);
  });
}).listen(8126);

const navegador = await chromium.launch();
const pagina = await navegador.newPage({ viewport: { width: 5200, height: 1300 }, deviceScaleFactor: 1 });
await pagina.goto('http://localhost:8126/proceso-operacional-con-ia/proceso-operacional-con-ia.html');
await pagina.waitForSelector('[data-element-id="c1"]', { timeout: 30000 });
await pagina.waitForTimeout(2000);
const caja = await pagina.evaluate(() => {
  const ids = ['bo1', 'c1', 'c4a', 'c2', 'vw', 'c3', 'p1', 'cr', 'mg', 'c5', 'c4b', 'c4c', 'ac', 'sy', 'pf'];
  const r = ids.map((id) => document.querySelector(`[data-element-id="${id}"]`))
    .filter(Boolean).map((e) => e.getBoundingClientRect());
  return { x: Math.min(...r.map((b) => b.left)), y: Math.min(...r.map((b) => b.top)),
    x2: Math.max(...r.map((b) => b.right)), y2: Math.max(...r.map((b) => b.bottom)) };
});
const m = 40;
await pagina.screenshot({ path: process.argv[2],
  clip: { x: caja.x - m, y: caja.y - m - 20, width: caja.x2 - caja.x + 2 * m, height: caja.y2 - caja.y + 2 * m + 20 } });
console.log('recorte', caja);
await navegador.close();
servidor.close();

