// Capturas de las paginas publicas de GitHub del issue y la PR del sandbox. Uso: node capturar-github.mjs <carpeta>
import { chromium } from 'file:///./base-conocimiento/eval-100-preguntas/node_modules/playwright/index.mjs';

const SALIDA = process.argv[2];
const BASE = 'https://github.com/G3A/base-conocimiento-sandbox';
const paginas = [
  ['gh-issue-54', `${BASE}/issues/54`],
  ['gh-pr-55', `${BASE}/pull/55`],
  ['gh-pr-55-commits', `${BASE}/pull/55/commits`],
  ['gh-pr-55-checks', `${BASE}/pull/55/checks`],
];
const navegador = await chromium.launch();
const pagina = await navegador.newPage({ viewport: { width: 1280, height: 900 }, colorScheme: 'light', locale: 'es-ES' });
for (const [nombre, url] of paginas) {
  await pagina.goto(url, { waitUntil: 'domcontentloaded' });
  await pagina.waitForTimeout(4000);
  await pagina.screenshot({ path: `${SALIDA}/${nombre}.png` });
  console.log(nombre, 'ok');
}
await navegador.close();

// Captura el comentario de la decision de interfaz en el issue #54 del sandbox. Uso: node capturar-decision.mjs <png>
import { chromium } from 'file:///./base-conocimiento/eval-100-preguntas/node_modules/playwright/index.mjs';

const navegador = await chromium.launch();
const pagina = await navegador.newPage({ viewport: { width: 1280, height: 900 }, colorScheme: 'light' });
await pagina.goto('https://github.com/G3A/base-conocimiento-sandbox/issues/54', { waitUntil: 'domcontentloaded' });
await pagina.waitForTimeout(4000);
const titulo = pagina.getByRole('heading', { name: /Decisión de interfaz/ }).first();
await titulo.scrollIntoViewIfNeeded();
await pagina.evaluate(() => window.scrollBy(0, -120));
await pagina.waitForTimeout(800);
await pagina.screenshot({ path: process.argv[2] });
await navegador.close();

