// Recorta un PNG con el mismo marco: node recortar-png.mjs <entrada> <salida> <x> <y> <ancho> <alto>
import fs from 'node:fs';
import { chromium } from 'file:///./base-conocimiento/eval-100-preguntas/node_modules/playwright/index.mjs';

const [entrada, salida, x, y, w, h] = process.argv.slice(2);
const datos = fs.readFileSync(entrada).toString('base64');
const navegador = await chromium.launch();
const pagina = await navegador.newPage({ viewport: { width: 2000, height: 1400 } });
await pagina.setContent(`<body style="margin:0"><img id="i" src="data:image/png;base64,${datos}"></body>`);
await pagina.waitForFunction(() => document.getElementById('i').complete);
await pagina.screenshot({ path: salida, clip: { x: +x, y: +y, width: +w, height: +h } });
await navegador.close();

