  // frontmatter entre al alcance, su cabecera no se puede envolver.
  const finFrontmatter = lineas[0] === '---' ? lineas.indexOf('---', 1) : -1;
  let max = 0;
  let peor = 0;
  lineas.forEach((linea, i) => {
    const ancho = [...linea].length;
    if (ancho <= TOPE) return;
    if (i <= finFrontmatter) return;
    // Una celda de tabla no se envuelve; el ADR-0003 ya tiene filas de 250.
    if (/^\s*\|/.test(linea)) return;
    if (inquebrantable(linea)) return;
    if (ancho <= max) return;
    max = ancho;
    peor = i + 1;

entrada.content:
// Envuelve a 100 caracteres las lineas de un .md de reveal: parte etiquetas HTML pegadas y luego
// la prosa en espacios. Deja las filas de tabla. Uso: node envolver.mjs <archivo>
import fs from 'node:fs';

const TOPE = 100;
const ruta = process.argv[2];
const largo = (s) => [...s].length;
const salida = [];
for (const linea of fs.readFileSync(ruta, 'utf8').split('\n')) {
  if (largo(linea) <= TOPE || /^\s*\|/.test(linea)) { salida.push(linea); continue; }
  const piezas = linea.trimStart().startsWith('<') ? linea.split(/(?<=>)(?=<)/) : [linea];
  for (const pieza of piezas) {
    if (largo(pieza) <= TOPE) { salida.push(pieza); continue; }
    const m = /^(\s*)((?:[-*]|\d+\.)\s+)?/.exec(pieza);
    const sangria = m[1] + ' '.repeat(m[2] ? m[2].length : 0);
    let actual = '';
    for (const palabra of pieza.split(' ')) {
      const candidata = actual ? `${actual} ${palabra}` : palabra;
      if (largo(candidata) > TOPE && actual.trim()) {
        salida.push(actual);
        actual = sangria + palabra;
      } else {
        actual = candidata;
      }
    }
    salida.push(actual);
  }
}
fs.writeFileSync(ruta, salida.join('\n'));

